css:
.sl-gallery-before-after { padding-block: clamp(3rem, 6vw, 5rem); padding-inline: clamp(1rem, 3vw, 2rem); background-color: var(--smartlearn-bg); font-family: var(--smartlearn-body-font, system-ui, sans-serif); }
.sl-gallery-before-after .sl-container { max-width: 1140px; width: 100%; margin-inline: auto; }
.sl-gallery-before-after .sl-ba-header { text-align: center; margin-bottom: 3rem; max-width: 640px; margin-inline: auto; }
.sl-gallery-before-after .sl-ba-header .sl-section-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.75rem, 3.5vw, 2.25rem); font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.5rem; }
.sl-gallery-before-after .sl-ba-header .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin: 0; }
.sl-gallery-before-after .sl-ba-container { position: relative; width: 100%; max-width: 1000px; margin-inline: auto; aspect-ratio: 16/9; border-radius: var(--smartlearn-radius, 1rem); overflow: hidden; box-shadow: 0 20px 40px rgba(0, 0, 0, 0.12); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); }
.sl-gallery-before-after .sl-ba-image { position: absolute; inset: 0; width: 100%; height: 100%; }
.sl-gallery-before-after .sl-ba-image img { width: 100%; height: 100%; object-fit: cover; display: block; }
.sl-gallery-before-after .sl-img-after { clip-path: inset(0 50% 0 0); }
[dir="rtl"] .sl-gallery-before-after .sl-img-after { clip-path: inset(0 0 0 50%); }
.sl-gallery-before-after .sl-ba-label { position: absolute; top: 1.25rem; padding: 0.45rem 0.9rem; background: rgba(15, 23, 42, 0.78); color: #ffffff; font-weight: 600; border-radius: 999px; backdrop-filter: blur(4px); font-size: 0.85rem; max-width: 42%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sl-gallery-before-after .sl-label-before { inset-inline-end: 1.25rem; }
.sl-gallery-before-after .sl-label-after { inset-inline-start: 1.25rem; }
.sl-gallery-before-after .sl-ba-slider { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: ew-resize; z-index: 10; margin: 0; touch-action: pan-y; }
.sl-gallery-before-after .sl-ba-handle { position: absolute; top: 0; bottom: 0; inset-inline-start: 50%; width: 4px; background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); transform: translateX(-50%); pointer-events: none; z-index: 5; box-shadow: 0 0 10px rgba(0, 0, 0, 0.45); display: flex; align-items: center; justify-content: center; }
[dir="rtl"] .sl-gallery-before-after .sl-ba-handle { transform: translateX(50%); }
.sl-gallery-before-after .sl-ba-handle svg { background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); width: 42px; height: 42px; border-radius: 50%; padding: 9px; box-shadow: 0 2px 8px rgba(0, 0, 0, 0.35); flex-shrink: 0; }
.sl-gallery-before-after .sl-ba-slider:focus-visible + .sl-ba-handle svg { outline: 3px solid var(--smartlearn-primary); outline-offset: 4px; }
@media (max-width: 767px) { .sl-gallery-before-after .sl-ba-container { aspect-ratio: 4/3; } .sl-gallery-before-after .sl-ba-label { top: 0.75rem; font-size: 0.75rem; padding: 0.35rem 0.7rem; } }

js:
(function() {
  var init = function() {
    document.querySelectorAll('.sl-gallery-before-after').forEach(function(root) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var slider = root.querySelector('.sl-ba-slider');
      var afterImg = root.querySelector('.sl-img-after');
      var handle = root.querySelector('.sl-ba-handle');
      if (!slider || !afterImg || !handle) return;
      var update = function(rawVal) {
        var val = Math.max(0, Math.min(100, Number(rawVal)));
        var isRtl = getComputedStyle(root).direction === 'rtl';
        afterImg.style.clipPath = isRtl ? ('inset(0 0 0 ' + (100 - val) + '%)') : ('inset(0 ' + (100 - val) + '% 0 0)');
        handle.style.insetInlineStart = val + '%';
        slider.setAttribute('aria-valuetext', val + '%');
      };
      update(slider.value);
      slider.addEventListener('input', function(e) { update(e.target.value); });
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
